## Core Operations

### Create Workspace (claim.rs)

```rust
pub fn create_workspace(workspace_root: &Path, task_id: &str) -> Result<WorkspaceInfo> {
    let workspace_path = workspace_root.join(".bacchus/workspaces").join(task_id);

    // Create workspace explicitly from main bookmark
    // -r main ensures we always fork from the integration point, not current root revision
    run_jj(workspace_root, &[
        "workspace", "add",
        "--name", task_id,
        "-r", "main",  // Pin to main bookmark
        workspace_path.to_str().unwrap(),
    ])?;

    Ok(WorkspaceInfo {
        task_id: task_id.to_string(),
        path: workspace_path,
    })
}
```

### Mark Ready (agent signals completion)

```rust
pub fn mark_ready(workspace_root: &Path, task_id: &str) -> Result<()> {
    // Validate single-commit workflow: workspace should have exactly one commit above main
    let commit_count_output = run_jj(workspace_root, &[
        "log",
        "--no-graph",
        "-r", &format!("main..{}@", task_id),  // Commits between main and workspace tip
        "-T", "commit_id\n",
    ])?;
    let commit_count = commit_count_output.lines().filter(|l| !l.is_empty()).count();

    if commit_count == 0 {
        return Err(anyhow!("Workspace {} has no commits above main", task_id));
    }
    if commit_count > 1 {
        return Err(anyhow!(
            "Workspace {} has {} commits above main. Squash to single commit before marking ready.",
            task_id, commit_count
        ));
    }

    // Get current working copy commit from workspace
    let output = run_jj(workspace_root, &[
        "--at-operation=@",
        "log",
        "--no-graph",
        "-r", &format!("{}@", task_id),
        "-T", "commit_id",
    ])?;
    let commit_id = output.trim().to_string();

    if commit_id.is_empty() {
        return Err(anyhow!("Failed to get commit ID for workspace {}", task_id));
    }

    // Update task status AND persist ready_commit_id for diagnostics
    // NOTE: This commit_id will change after rebase - we re-capture post-rebase
    // But storing pre-rebase ID helps diagnose stuck releases
    mark_task_ready(task_id, &commit_id)?;

    Ok(())
}

// In src/tasks.rs
pub fn mark_task_ready(task_id: &str, ready_commit_id: &str) -> Result<()> {
    with_db(|conn| {
        let now = now_ms();
        conn.execute(
            "UPDATE tasks_v2 SET
                status = 'ready_for_release',
                ready_commit_id = ?1,
                updated_at = ?2
             WHERE id = ?3",
            params![ready_commit_id, now, task_id],
        )?;
        Ok(())
    })
}

pub fn store_release_commit_id(task_id: &str, release_commit_id: &str) -> Result<()> {
    with_db(|conn| {
        let now = now_ms();
        conn.execute(
            "UPDATE tasks_v2 SET
                release_commit_id = ?1,
                updated_at = ?2
             WHERE id = ?3",
            params![release_commit_id, now, task_id],
        )?;
        Ok(())
    })
}
```

### Release Workspace (orchestrator only)

```rust
pub fn release_next_ready() -> Result<Option<ReleaseResult>> {
    // Use IMMEDIATE transaction for write-intent locking
    // This prevents concurrent orchestrators from racing
    let task = with_db(|conn| {
        // BEGIN IMMEDIATE acquires write lock immediately
        conn.execute_batch("BEGIN IMMEDIATE")?;

        // Atomic select-and-update: claim oldest ready task if no releasing
        // Single statement prevents TOCTOU race
        let now = now_ms();
        let rows_affected = conn.execute(
            "UPDATE tasks_v2
             SET status = 'releasing', release_started_at = ?1
             WHERE id = (
                 SELECT id FROM tasks_v2
                 WHERE status = 'ready_for_release'
                 AND deleted_at IS NULL
                 AND NOT EXISTS (
                     SELECT 1 FROM tasks_v2
                     WHERE status = 'releasing'
                     AND deleted_at IS NULL  -- Ignore deleted tasks in lock check
                 )
                 ORDER BY updated_at ASC
                 LIMIT 1
             )",
            params![now],
        )?;

        if rows_affected == 0 {
            conn.execute_batch("COMMIT")?;
            return Ok(None);
        }

        // Fetch the task we just updated
        let task: SqliteTask = conn.query_row(
            "SELECT * FROM tasks_v2 WHERE status = 'releasing' AND deleted_at IS NULL",
            [],
            map_task,
        )?;

        conn.execute_batch("COMMIT")?;
        Ok(Some(task))
    })?;

    let task = match task {
        Some(t) => t,
        None => return Ok(None),
    };

    // Now perform jj operations outside the transaction
    let result = do_release(&task.id);

    // Update final status based on result
    match result {
        Ok(ReleaseResult::Success) => {
            update_task_status(&task.id, "closed")?;
            Ok(Some(ReleaseResult::Success))
        }
        Ok(ReleaseResult::Conflicts { files }) => {
            update_task_status(&task.id, "needs_resolution")?;
            Ok(Some(ReleaseResult::Conflicts { files }))
        }
        Err(e) => {
            // Distinguish recoverable vs unrecoverable errors
            let err_str = e.to_string().to_lowercase();

            // Specific jj error patterns for missing workspace
            let is_workspace_missing =
                err_str.contains("no workspace named") ||
                err_str.contains("workspace not found") ||
                err_str.contains("no such workspace");

            // Specific jj error patterns for missing revision
            let is_revision_missing =
                err_str.contains("revset") && err_str.contains("didn't match") ||
                err_str.contains("no such revision");

            if is_workspace_missing || is_revision_missing {
                // Workspace or revision missing - needs recreation
                // Don't reset to ready_for_release (would loop forever)
                reset_sqlite_task(&task.id, "open")?;
            } else {
                // Transient error (network, lock, I/O, etc) - retry allowed
                reset_sqlite_task(&task.id, "ready_for_release")?;
            }
            Err(e)
        }
    }
}

fn do_release(task_id: &str) -> Result<ReleaseResult> {
    let workspace_root = get_workspace_root()?;

    // 1. Rebase task workspace onto main
    let rebase_status = run_jj_with_status(&workspace_root, &[
        "rebase",
        "-r", &format!("{}@", task_id),
        "-d", "main",
    ])?;

    // 2. Check rebase exit status for hard errors
    if !rebase_status.success() {
        // Check if it's a conflict (soft error) or hard error
        let has_conflicts = check_workspace_conflicts(&workspace_root, task_id)?;
        if has_conflicts {
            let conflict_files = get_conflict_files(&workspace_root, task_id)?;
            return Ok(ReleaseResult::Conflicts { files: conflict_files });
        }
        // Hard error - propagate
        return Err(anyhow!("jj rebase failed with exit code: {:?}", rebase_status.code()));
    }

    // 3. Double-check for conflicts (jj may return 0 even with conflicts)
    let has_conflicts = check_workspace_conflicts(&workspace_root, task_id)?;
    if has_conflicts {
        let conflict_files = get_conflict_files(&workspace_root, task_id)?;
        return Ok(ReleaseResult::Conflicts { files: conflict_files });
    }

    // 4. Get the NEW commit ID after rebase
    let new_commit_id = run_jj(&workspace_root, &[
        "log",
        "--no-graph",
        "-r", &format!("{}@", task_id),
        "-T", "commit_id",
    ])?.trim().to_string();

    if new_commit_id.is_empty() {
        return Err(anyhow!("Failed to get commit ID after rebase"));
    }

    // 5. Store post-rebase commit ID for stuck release detection
    // This allows cleanup_stuck_release to check if work was actually merged
    store_release_commit_id(task_id, &new_commit_id)?;

    // 6. Advance main bookmark to rebased commit
    run_jj(&workspace_root, &[
        "bookmark", "set", "main",
        "-r", &new_commit_id,
    ])?;

    // 7. Delete workspace
    run_jj(&workspace_root, &[
        "workspace", "forget", task_id,
    ])?;

    // 8. Clean up workspace directory
    let workspace_path = workspace_root.join(".bacchus/workspaces").join(task_id);
    if workspace_path.exists() {
        std::fs::remove_dir_all(&workspace_path)?;
    }

    Ok(ReleaseResult::Success)
}

fn check_workspace_conflicts(workspace_root: &Path, task_id: &str) -> Result<bool> {
    // Check if workspace has conflict markers
    let output = run_jj(workspace_root, &[
        "log",
        "--no-graph",
        "-r", &format!("{}@", task_id),
        "-T", "conflict",
    ])?;

    Ok(output.trim() == "true")
}

fn get_conflict_files(workspace_root: &Path, task_id: &str) -> Result<Vec<String>> {
    let output = run_jj(workspace_root, &[
        "resolve", "--list",
        "-r", &format!("{}@", task_id),
    ])?;

    Ok(output.lines().map(String::from).collect())
}
