### Stale Detection (stale.rs)

```rust
pub fn find_stale_workspaces(threshold_minutes: i64) -> Result<Vec<StaleWorkspace>> {
    let cutoff = now_ms() - (threshold_minutes * 60 * 1000);

    with_db(|conn| {
        // Find stale in_progress tasks (by claimed_at)
        // Exclude 'releasing' - those are handled separately or are short-lived
        conn.prepare(
            "SELECT id, claimed_by, claimed_at FROM tasks_v2
             WHERE status = 'in_progress'
             AND claimed_at < ?1
             AND deleted_at IS NULL"
        )?
        .query_map([cutoff], |row| {
            Ok(StaleWorkspace {
                task_id: row.get(0)?,
                agent_id: row.get(1)?,
                claimed_at: row.get(2)?,
            })
        })?
        .collect()
    })
}

pub fn find_stuck_releases(threshold_minutes: i64) -> Result<Vec<StuckRelease>> {
    // Separate function for stuck releases - use release_started_at
    let cutoff = now_ms() - (threshold_minutes * 60 * 1000);

    with_db(|conn| {
        conn.prepare(
            "SELECT id, release_started_at FROM tasks_v2
             WHERE status = 'releasing'
             AND release_started_at < ?1
             AND deleted_at IS NULL"
        )?
        .query_map([cutoff], |row| {
            Ok(StuckRelease {
                task_id: row.get(0)?,
                release_started_at: row.get(1)?,
            })
        })?
        .collect()
    })
}

pub fn cleanup_stuck_release(task_id: &str) -> Result<()> {
    // Reset a stuck releasing task - with proper verification
    let workspace_root = get_workspace_root()?;

    // Step 1: Check if workspace is registered with jj (exact name match)
    let workspace_list = run_jj(&workspace_root, &[
        "workspace", "list",
        "--template", "{name}\n",  // Get just workspace names
    ])?;
    let workspace_registered = workspace_list.lines()
        .any(|name| name.trim() == task_id);  // Exact match, not substring

    // Step 2: Get release_commit_id (post-rebase) from task
    // This is the commit ID AFTER rebase, which will be in main if release succeeded
    let task = get_sqlite_task(task_id)?;
    let release_commit_id = task.release_commit_id.as_deref();

    // Step 3: Check if the post-rebase commit is reachable from main
    // Use release_commit_id (post-rebase), not ready_commit_id (pre-rebase)
    let work_in_main = if let Some(commit_id) = release_commit_id {
        // Check if commit is an ancestor of main using ::main (ancestors of main)
        // This works even if main has advanced past this commit
        let output = run_jj(&workspace_root, &[
            "log",
            "-r", &format!("{} & ::main", commit_id),  // Commit AND ancestors of main
            "--no-graph",
            "-T", "commit_id",
        ]).unwrap_or_default();
        // If output contains our commit ID, it's reachable from main
        !output.trim().is_empty() && output.contains(commit_id)
    } else {
        // No release_commit_id means rebase never completed successfully
        false
    };

    // Step 4: Decide action based on state
    if work_in_main {
        // Work was already merged - close the task
        update_task_status(task_id, "closed")?;
    } else if workspace_registered {
        // Workspace exists in jj - safe to retry release
        reset_sqlite_task(task_id, "ready_for_release")?;
    } else {
        // Workspace gone, work not in main - needs recreation
        // Reset to open so agent can re-claim
        reset_sqlite_task(task_id, "open")?;
    }

    Ok(())
}

pub fn cleanup_stale_workspace(task_id: &str) -> Result<()> {
    let workspace_root = get_workspace_root()?;

    // Forget the workspace (preserves commits in repo)
    let _ = run_jj(&workspace_root, &["workspace", "forget", task_id]);

    // Remove directory
    let workspace_path = workspace_root.join(".bacchus/workspaces").join(task_id);
    if workspace_path.exists() {
        std::fs::remove_dir_all(&workspace_path)?;
    }

    // Reset task to open
    reset_sqlite_task(task_id, "open")?;

    Ok(())
}
```

